<?php
require_once __DIR__ . '/auth.php';
require_once __DIR__ . '/config.php';
require_once __DIR__ . '/agenda.php';
startSecureSession();
if (!isAuthenticated()) { header('Location: ' . appPath('/access/login.php')); exit; }

$cfg = appConfig();
$pdo = new PDO("mysql:host={$cfg['db_host']};dbname={$cfg['db_name']};charset={$cfg['db_charset']}", $cfg['db_user'], $cfg['db_pass'], [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION, PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC]);
ensureAgendaTables($pdo);
$profileStmt = $pdo->prepare('SELECT id FROM profissionais WHERE user_id = :user_id LIMIT 1');
$profileStmt->execute([':user_id' => (int) currentUserId()]);
$professionalId = (int) $profileStmt->fetchColumn();
if (!$professionalId) { header('Location: ' . appPath('/secure/save_profile.php')); exit; }

$csrf = ensureCsrfToken();
$message = '';
$error = '';
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    if (!verifyCsrfTokenOrFail($_POST['csrf_token'] ?? null)) {
        $error = 'Não foi possível salvar. Atualize a página e tente novamente.';
    } else {
        $hours = [];
        for ($day = 1; $day <= 7; $day++) {
            $start = trim((string) ($_POST['start_' . $day] ?? '07:00'));
            $end = trim((string) ($_POST['end_' . $day] ?? '18:00'));
            $hours[(string) $day] = ['active' => isset($_POST['active_' . $day]), 'start' => preg_match('/^\d{2}:\d{2}$/', $start) ? $start : '07:00', 'end' => preg_match('/^\d{2}:\d{2}$/', $end) ? $end : '18:00'];
        }
        $duration = (int) ($_POST['duracao_minutos'] ?? 60);
        $interval = (int) ($_POST['intervalo_minutos'] ?? 15);
        $lead = (int) ($_POST['antecedencia_minutos'] ?? 120);
        $limit = (int) ($_POST['limite_diario'] ?? 0);
        $stmt = $pdo->prepare('UPDATE agenda_configuracoes SET agenda_ativa = :active, duracao_minutos = :duration, intervalo_minutos = :interval, antecedencia_minutos = :lead, confirmacao_manual = :manual, limite_diario = :limit, horarios_json = :hours WHERE profissional_id = :id');
        $stmt->execute([':active' => isset($_POST['agenda_ativa']) ? 1 : 0, ':duration' => max(15, min(480, $duration)), ':interval' => max(0, min(120, $interval)), ':lead' => max(0, min(10080, $lead)), ':manual' => ($_POST['confirmacao'] ?? 'auto') === 'manual' ? 1 : 0, ':limit' => max(0, min(50, $limit)), ':hours' => json_encode($hours, JSON_UNESCAPED_UNICODE), ':id' => $professionalId]);
        $message = 'Configurações da agenda salvas.';
    }
}
$agenda = agendaGetConfig($pdo, $professionalId);
$week = [1 => 'Seg', 2 => 'Ter', 3 => 'Qua', 4 => 'Qui', 5 => 'Sex', 6 => 'Sáb', 7 => 'Dom'];
function optionSelected(int $value, $current): string { return (int) $current === $value ? 'selected' : ''; }
?>
